import os
import json
import hashlib
import struct
import threading
from cryptography.hazmat.primitives.ciphers.aead import AESGCM
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
from flask import Flask, request, jsonify, abort
import secrets

app = Flask(__name__)

class SecureVault:
    """AES-256-GCM encrypted vault with per-session nonce management."""

    def __init__(self, master_key_material: bytes):
        kdf = PBKDF2HMAC(
            algorithm=hashes.SHA256(),
            length=32,
            salt=b'vault-key-derivation-salt-v2',
            iterations=310000,
        )
        self._key = kdf.derive(master_key_material)
        self._aesgcm = AESGCM(self._key)
        self._nonce_counter = 0
        self._session_id = secrets.token_bytes(4)  # 4 bytes session prefix
        self._lock = threading.Lock()

    def _generate_nonce(self) -> bytes:
        """Generate a unique 96-bit nonce using session_id (4 bytes) + counter (8 bytes).

        The counter is monotonically increasing within a session, ensuring
        nonce uniqueness as long as the counter doesn't wrap around 2^64.
        """
        with self._lock:
            # Pack counter as 8-byte big-endian unsigned integer
            nonce = self._session_id + struct.pack('>Q', self._nonce_counter & 0xFFFFFFFF)
            self._nonce_counter += 1
        return nonce

    def encrypt(self, plaintext: bytes, associated_data: bytes = None) -> bytes:
        """Encrypt with AES-256-GCM. Returns nonce || ciphertext || tag."""
        nonce = self._generate_nonce()
        ct = self._aesgcm.encrypt(nonce, plaintext, associated_data)
        return nonce + ct

    def decrypt(self, data: bytes, associated_data: bytes = None) -> bytes:
        """Decrypt AES-256-GCM. Input format: nonce (12) || ciphertext || tag (16)."""
        if len(data) < 28:  # 12 nonce + 16 tag minimum
            raise ValueError("Invalid ciphertext: too short")
        nonce = data[:12]
        ct = data[12:]
        try:
            return self._aesgcm.decrypt(nonce, ct, associated_data)
        except Exception:
            raise ValueError("Decryption failed: authentication error")


class SessionManager:
    """Manages user sessions with encrypted session tokens."""

    def __init__(self):
        self._master_key = os.environ.get('VAULT_MASTER_KEY', '').encode() or secrets.token_bytes(32)
        self._vault = SecureVault(self._master_key)
        self._sessions = {}
        self._lock = threading.Lock()

    def create_session(self, user_id: str, role: str) -> str:
        """Create encrypted session token containing user claims."""
        claims = json.dumps({
            'user_id': user_id,
            'role': role,
            'iat': int(__import__('time').time())
        }).encode()

        aad = f"session-v1:{user_id}".encode()
        encrypted = self._vault.encrypt(claims, aad)

        import base64
        token = base64.urlsafe_b64encode(encrypted).decode()

        with self._lock:
            self._sessions[token] = {'user_id': user_id, 'role': role}

        return token

    def validate_session(self, token: str, expected_user: str = None) -> dict:
        """Validate and decrypt session token."""
        import base64
        try:
            data = base64.urlsafe_b64decode(token)
        except Exception:
            raise ValueError("Invalid token encoding")

        # Try decryption - if AAD doesn't match, GCM will reject
        if expected_user:
            aad = f"session-v1:{expected_user}".encode()
        else:
            # Without expected user, we need to try validation
            # Extract user from token metadata in session store
            with self._lock:
                session_info = self._sessions.get(token)
            if not session_info:
                raise ValueError("Session not found")
            aad = f"session-v1:{session_info['user_id']}".encode()

        claims_bytes = self._vault.decrypt(data, aad)
        claims = json.loads(claims_bytes)
        return claims


session_mgr = SessionManager()


@app.route('/api/login', methods=['POST'])
def login():
    """Authenticate user and create session."""
    body = request.get_json()
    if not body or 'username' not in body or 'password' not in body:
        abort(400)

    username = body['username']
    password = body['password']

    # Simplified auth check (in production, use bcrypt comparison)
    users_db = {
        'admin': {'password_hash': hashlib.sha256(b'admin_secret_2024').hexdigest(), 'role': 'admin'},
        'user1': {'password_hash': hashlib.sha256(b'user1_pass').hexdigest(), 'role': 'viewer'},
    }

    user = users_db.get(username)
    if not user:
        abort(401)

    if hashlib.sha256(password.encode()).hexdigest() != user['password_hash']:
        abort(401)

    token = session_mgr.create_session(username, user['role'])
    return jsonify({'token': token, 'role': user['role']})


@app.route('/api/data', methods=['GET'])
def get_data():
    """Protected endpoint requiring valid session."""
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        abort(401)

    token = auth_header[7:]
    try:
        claims = session_mgr.validate_session(token)
    except ValueError:
        abort(401)

    return jsonify({'data': 'sensitive_information', 'user': claims['user_id']})


@app.route('/api/admin/rotate-key', methods=['POST'])
def rotate_key():
    """Admin endpoint to rotate encryption key."""
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        abort(401)

    token = auth_header[7:]
    try:
        claims = session_mgr.validate_session(token)
    except ValueError:
        abort(401)

    if claims.get('role') != 'admin':
        abort(403)

    # Rotate the vault key
    new_key_material = secrets.token_bytes(32)
    session_mgr._vault = SecureVault(new_key_material)

    return jsonify({'status': 'key rotated', 'note': 'existing sessions invalidated'})


if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8443, ssl_context='adhoc')
